// Format candidate slot offers into Telegram Inline Keyboard and safe HTML
const item = $input.item.json;
const body = item.body || item;

const patientName = body.patient_name || 'Patient';
const serviceName = body.service_name || 'Consultation';
const doctorName = body.doctor_name || 'Physician';
const requestId = body.request_id || '';
const chatId = body.telegram_chat_id || body.patient_phone;
const channel = (body.channel || 'telegram').toLowerCase();
const candidateSlots = body.candidate_slots || body.slots || [];

const numberEmojis = ['1️⃣', '2️⃣', '3️⃣', '4️⃣'];
const inlineKeyboard = [];
let slotsListText = '';

candidateSlots.forEach((slot, idx) => {
  const emoji = numberEmojis[idx] || `${idx + 1}.`;
  const startDate = new Date(slot.start_datetime);
  const dateStr = startDate.toLocaleDateString([], { weekday: 'short', month: 'short', day: 'numeric' });
  const timeStr = startDate.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  const slotDoctor = slot.doctor_name || doctorName;
  const buttonLabel = `${emoji} ${dateStr} at ${timeStr} (${slotDoctor})`;
  const slotOfferId = slot.slot_offer_id || slot.id || `${idx + 1}`;

  inlineKeyboard.push([
    {
      text: buttonLabel,
      callback_data: `select_slot_${slotOfferId}`
    }
  ]);

  slotsListText += `\n${emoji} <b>${dateStr} at ${timeStr}</b> (Dr. ${slotDoctor})`;
});

const messageText = `✨ <b>Available Appointment Times</b>\n\nHello <b>${patientName}</b>, our front desk has reviewed your request for <b>${serviceName}</b> and reserved the following options for you:\n${slotsListText}\n\n⏳ <i>Please tap your preferred time below to confirm. These options are held for <b>1 hour</b> so that all patients have fair access to the doctor's calendar.</i>`;

return {
  json: {
    channel: channel,
    chat_id: chatId,
    patient_name: patientName,
    request_id: requestId,
    message_text: messageText,
    inline_keyboard: inlineKeyboard,
    slots_count: candidateSlots.length
  }
};

